/* GeoSR editorial homepage — concept imagery is replaced through documented media slots */
const expertiseScenes = [
  {k:'관측과 조사',e:'Observation & survey',leadK:'현장을 정밀하게',leadE:'Closer to the field',bodyK:'육상에서 하천과 해양까지\n측량과 현장 관측으로 환경의 기초 자료를 확보합니다',bodyE:'Precision surveys and observations\nacross land, rivers and oceans',image:'coastal-survey-source.png',source:true,tagsK:['육상·수로 측량','해양 관측','무인 관측'],tagsE:['Land & hydrographic surveys','Ocean observation','Uncrewed systems'],page:'equipment'},
  {k:'환경과 생태',e:'Environment & ecology',leadK:'환경을 깊이 있게',leadE:'A deeper understanding',bodyK:'수질과 퇴적물의 화학분석부터 생태 조사까지\n다양한 관점에서 환경의 상태를 평가합니다',bodyE:'Chemical analysis and ecological surveys\nreveal the condition of aquatic environments',image:'analysis-concept.png',tagsK:['환경 분석','생태 조사','환경 평가'],tagsE:['Chemical analysis','Ecological surveys','Environmental assessment'],page:'business',params:{id:84}},
  {k:'수치모델과 예측',e:'Modelling & prediction',leadK:'변화를 예측하다',leadE:'Understand what comes next',bodyK:'기상과 유역에서 하천과 연안까지\n수치모델로 환경 변화와 재해 영향을 분석합니다',bodyE:'Numerical models investigate environmental change\nand hazard impacts across watersheds and coasts',image:'coastal-model-v3.png',tagsK:['수환경 모델','재해 예측','영향 분석'],tagsE:['Aquatic models','Hazard prediction','Impact analysis'],page:'business',params:{id:46}},
  {k:'AI와 원격탐사',e:'AI & remote sensing',leadK:'더 넓게 분석하다',leadE:'A wider perspective',bodyK:'위성영상과 환경 데이터에 AI를 적용해\n예측과 탐지의 가능성을 넓혀갑니다',bodyE:'AI and satellite imagery extend our ability\nto predict change and detect patterns',image:'satellite-layers-v3.png',tagsK:['환경 AI','위성영상','공간정보'],tagsE:['Environmental AI','Satellite imagery','Spatial information'],page:'business',params:{id:61}}
];

function expertisePanel(i=0){const d=expertiseScenes[i];return `<div class="expertise-photo" data-production-slot="expertise-${i+1}"><img src="assets/${d.image}" alt="${E(T(d.k,d.e))} — ${d.source?T('GeoSR 원본 자료','GeoSR source material'):T('영상 가안','film concept')}" loading="lazy"><span class="media-note">${d.source?T('GEOSR 현장 자료','GEOSR FIELD REFERENCE'):T('기술 연출 가안 · 실제 해석 결과 아님','VISUAL CONCEPT · NOT A VERIFIED ANALYSIS')}</span></div><div class="expertise-details"><span class="scene-index">0${i+1} / 04</span><h3>${T(d.leadK,d.leadE)}</h3><p>${T(d.bodyK,d.bodyE).replaceAll('\n','<br>')}</p><div class="expertise-tags">${(en?d.tagsE:d.tagsK).map(t=>`<span>${t}</span>`).join('')}</div>${A(U(d.page,d.params||{}),'관련 기술 보기','Explore the technology','plain-arrow')}</div>`}

function home(){return `
<section class="hero hero-new" data-production-slot="geosr-hero">
  <img class="hero-bg" src="assets/coastal-model-v3.png" alt="${T('GeoSR 브랜드 영상 가안 — 국내 연안 자료를 바탕으로 만든 기술 연출 가안','GeoSR brand film concept — concept based on Korean coastal source imagery')}" fetchpriority="high">
  <div class="hero-shade"></div><div class="hero-coordinate" aria-hidden="true"><span>FIELD / SCIENCE / TECHNOLOGY</span><i></i></div>
  <div class="hero-copy"><p class="eyebrow">GEOSYSTEM RESEARCH CORPORATION</p><h1 class="earth-title">Earth Systems<span>Intelligence</span></h1><div class="hero-copy-bottom"><p class="hero-description">${T('자연환경을 이해하고 예측하는 기술<br>현장 조사부터 수치모델링과 AI까지','Technology to understand our environment<br>From field observation to modelling and AI')}</p>${A('#expertise','GeoSR의 기술','Explore GeoSR','hero-link')}</div></div>
  <div class="hero-bottom"><span>GEOSR / ${T('해양·환경 기술','ENVIRONMENTAL TECHNOLOGY')}</span><a href="#expertise" class="scroll-line">SCROLL TO EXPLORE <span>↓</span></a><span>${T('영상 가안 · IMAGEGEN','FILM CONCEPT · IMAGEGEN')}</span></div>
</section>
<section class="intro-editorial" id="expertise"><div class="section-kicker"><span>01 / OUR EXPERTISE</span><span>SCIENCE IN ACTION</span></div><div class="intro-editorial-grid"><h2>${T('자연을 읽는 과학<br><span>현장을 바꾸는 기술</span>','Science for our world<br><span>Technology for the field</span>')}</h2><div><p>${T('지오시스템리서치는 육상과 하천에서 연안과 해양까지 다양한 환경을 조사하고 분석합니다','GeoSR investigates environments across land, rivers, coasts and oceans')}</p><p>${T('관측과 분석에서 수치모델과 AI까지<br>각 분야의 전문성으로 현장의 문제를 해결합니다','Field observation, analysis, modelling and AI<br>Specialist expertise shaped around real challenges')}</p>${A(U('company'),'GeoSR 소개','About GeoSR','plain-arrow')}</div></div></section>
<section class="expertise-theatre" aria-labelledby="expertise-heading"><div class="theatre-heading"><h2 id="expertise-heading">Explore our<br><span>expertise</span></h2><p>${T('분야를 선택해 GeoSR의 기술을 살펴보세요','Discover the disciplines behind our work')}</p></div><div class="expertise-tabs" role="tablist" aria-label="${T('주요 기술 분야','Expertise areas')}">${expertiseScenes.map((d,i)=>`<button id="expertise-tab-${i}" type="button" role="tab" aria-controls="expertise-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-expertise="${i}"><span>0${i+1}</span>${T(d.k,d.e)}<i>↗</i></button>`).join('')}</div><div id="expertise-panel" class="expertise-panel" role="tabpanel" aria-labelledby="expertise-tab-0">${expertisePanel()}</div><div class="theatre-bottom"><span>OBSERVATION / ENVIRONMENT / MODELLING / AI / SATELLITE / DATA</span>${A(U('business'),'기술·솔루션 전체보기','All technologies & solutions','plain-arrow')}</div></section>
<section class="platform-editorial"><div class="section-kicker"><span>02 / DIGITAL PLATFORMS</span><span>BUILT BY GEOSR</span></div><div class="platform-heading"><h2>${T('기술을 경험하는<br><span>새로운 방식</span>','A new way<br><span>to work with data</span>')}</h2><p>${T('GeoSR의 기술을 만나는 두 개의 플랫폼','Two distinct platforms from GeoSR')}</p></div><div class="platform-duo"><article class="platform-tile ax-tile" data-production-slot="ax-overview-film"><img src="assets/satellite-layers-v3.png" alt="${T('AX Platform 소개 영상 가안','AX Platform introduction film concept')}" loading="lazy"><div class="platform-tile-top"><span>APPLIED INTELLIGENCE</span><span>01</span></div><div class="platform-tile-body"><h3>AX<span>Platform</span></h3><p>${T('예측과 탐지에서 모니터링까지<br>목적에 맞게 활용하는 해양·환경 기술','From prediction and detection to monitoring<br>Purpose-built marine and environmental applications')}</p>${A(U('ax-platform'),'AX Platform 알아보기','Explore AX Platform','surface-link')}</div><small>${T('영상 가안 · IMAGEGEN','FILM CONCEPT · IMAGEGEN')}</small></article><article class="platform-tile geodap-tile"><div class="geodap-orbit" aria-hidden="true"></div><div class="platform-tile-top"><span>EARTH DATA PLATFORM</span><span>02</span></div><div class="platform-tile-body"><h3>GeoDAP<span class="geodap-sub">Earth Data Intelligence</span></h3><p>${T('관측과 모델에서 위성 데이터까지<br>지구환경 데이터를 탐색하는 독립 플랫폼','Observations, models and satellite data<br>An independent platform for Earth data exploration')}</p><a class="surface-link" href="https://www.geo-dap.com/" target="_blank" rel="noopener">${T('GeoDAP 바로가기','Open GeoDAP')} <span>↗</span></a></div><small>${T('별도 서비스 · 새 창으로 이동','INDEPENDENT SERVICE · OPENS IN A NEW TAB')}</small></article></div></section>
${credentialGallery()}
<section class="research-editorial-section"><div class="section-kicker"><span>04 / RESEARCH & NEWS</span>${A(U('research'),'연구·성과 전체보기','All research & achievements','plain-arrow')}</div><div class="research-title-row"><h2>Ideas into<br><span>impact</span></h2><p>${T('연구 현장에서 전하는 GeoSR의 소식','Research and news from GeoSR')}</p></div><div class="editorial-records">${[posts[1],posts[3],posts[2]].map((p,i)=>`<a class="editorial-record" href="${U(p[1]==='notice'?'news':'research',{id:p[0]})}"><span class="editorial-number">0${i+1}</span><div><span class="editorial-type">${T(...types.find(t=>t[0]===p[1]).slice(1))}</span><h3>${E(T(p[3],p[4]))}</h3></div><time>${p[2].replaceAll('-',' / ')}</time><span class="editorial-arrow">↗</span></a>`).join('')}</div></section>`}

function credentialGallery(){return `<section class="credential-section" id="credentials" aria-labelledby="credential-heading"><div class="section-kicker"><span>03 / PATENTS & CERTIFICATIONS</span><span>RESEARCH THAT BUILDS</span></div><div class="credential-intro"><h2 id="credential-heading">Built on<br><span>research</span></h2><div><p>${T('GeoSR의 특허와 기술 인증','Patents and certifications from GeoSR')}</p><p class="muted">${T('쌓아온 기술을 기록으로 확인하세요','Explore the records behind our expertise')}</p><div class="gallery-controls"><button type="button" data-gallery-step="-1" aria-label="${T('이전 자료','Previous document')}">←</button><span id="credential-status" aria-live="polite">01 / 07</span><button type="button" data-gallery-step="1" aria-label="${T('다음 자료','Next document')}">→</button></div></div></div><div class="credential-rail" tabindex="0" role="region" aria-label="${T('인증서·특허 가로 갤러리','Horizontal patent and certification gallery')}" aria-describedby="credential-hint"><div class="credential-loading">${T('자료를 불러오는 중','Loading documents')}</div></div><div class="credential-bottom"><p id="credential-hint">${T('좌우로 넘겨보기 · 자료를 선택하면 확대됩니다','Swipe or use the arrows · Select a document to enlarge')}</p><a href="${U('company')}#credential-library">${T('인증·면허·지식재산권 전체보기','Explore the document collection')} ↗</a></div></section><dialog id="credential-dialog" aria-labelledby="credential-dialog-title"><div class="document-modal-head"><h2 id="credential-dialog-title"></h2><button type="button" data-close-document aria-label="${T('닫기','Close')}">×</button></div><img alt=""><div class="document-modal-foot"><p>${T('기존 홈페이지에 공개된 자료의 사본','A copy of the record published on the original website')}</p><a target="_blank" rel="noopener">${T('문서 사본 열기','Open document copy')} ↗</a></div></dialog>`}

function modernFooter(){return `<section class="contact-editorial"><div class="contact-editorial-top"><p class="eyebrow">CONNECT WITH GEOSR</p><span>${T('사업과 연구의 다음 파트너','YOUR NEXT RESEARCH & ENGINEERING PARTNER')}</span></div><a href="${U('contact')}" class="contact-statement"><h2>Let’s move<br><span>forward</span></h2><span aria-hidden="true">↗</span></a><div class="contact-editorial-bottom"><p>${T('사업·기술 문의 및 연구 협력','Projects, technology enquiries and research partnerships')}</p><a href="mailto:admin@geosr.com">admin@geosr.com ↗</a></div></section><footer class="site-footer"><div class="footer-information"><div><a class="brand" href="${U('index')}"><img src="assets/logo.png" alt="GeoSR"></a><p>${T('지오시스템리서치','GeoSystem Research Corporation')}<br>${T('경기도 군포시 엘에스로 172 한림휴먼타워 306호','306 Hanlim Human Tower, 172 LS-ro, Gunpo-si, Korea')}</p><a href="tel:+823151805700">+82 31 5180 5700</a></div><div class="footer-navigation">${nav.map(n=>A(U(n[0]),n[1],n[2])).join('')}${A('https://www.geo-dap.com/','GeoDAP','GeoDAP')}</div><div class="footer-meta"><span>© GEOSYSTEM RESEARCH</span><p>${T('디자인 목업<br>생성 이미지는 영상 제작을 위한 가안입니다','DESIGN PROTOTYPE<br>Generated imagery represents proposed films')}</p>${A(U('equipment'),'관측·장비','Observation & equipment')}</div></div><div class="footer-wordmark" aria-hidden="true">GeoSR<span>®</span></div></footer>`}
